function usage() {
  console.log(`Usage:
  pnpm indexnow:seo-updates -- --priority
  pnpm indexnow:seo-updates -- --url https://gachia.com/en/wuwa/guides/banner-schedule-guide
  pnpm indexnow:seo-updates -- --path /en/wuwa/guides/banner-schedule-guide
  pnpm indexnow:seo-updates -- --priority --dry-run`);
}

function normalizeUrl(value) {
  if (value.startsWith('https://')) return value;
  if (value.startsWith('/')) return `${BASE_URL}${value}`;
  return `${BASE_URL}/${value}`;
}

function collectUrls(args) {
  const urls = new Set();

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg === '--help' || arg === '-h') {
      usage();
      process.exit(0);
    }

    if (arg === '--priority') {
      for (const [gameId, slug] of PRIORITY_GUIDES) {
        for (const locale of LOCALES) {
          urls.add(`${BASE_URL}/${locale}/${gameId}/guides/${slug}`);
        }
      }
      for (const priorityPath of PRIORITY_PATHS) {
        urls.add(normalizeUrl(priorityPath));
      }
      continue;
    }

    if (arg === '--url' || arg === '--path') {
      const next = args[i + 1];
      if (!next) throw new Error(`${arg} requires a value`);
      urls.add(normalizeUrl(next));
      i += 1;
      continue;
    }
  }

  return [...urls];
}

function validateUrls(urls) {
  for (const url of urls) {
    const parsed = new URL(url);
    if (parsed.protocol !== 'https:' || parsed.hostname !== 'gachia.com' || parsed.port) {
      throw new Error(`IndexNow only accepts production gachia.com URLs: ${url}`);
    }
  }
}

async function submit(urls, dryRun) {
  if (urls.length === 0) {
    usage();
    throw new Error('No URLs selected for IndexNow submission.');
  }

  validateUrls(urls);

  const payload = {
    host: 'gachia.com',
    key: INDEXNOW_KEY,
    keyLocation: `${BASE_URL}/${INDEXNOW_KEY}.txt`,
    urlList: urls,
  };

  if (dryRun) {
    console.log(JSON.stringify(payload, null, 2));
    return;
  }

  for (const endpoint of ENDPOINTS) {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    console.log(`${endpoint} -> ${response.status} (${urls.length} URLs)`);
  }
}

const args = process.argv.slice(2);
await submit(collectUrls(args), args.includes('--dry-run'));

import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { GAME_IDS } from '@gachia/core';

const BASE_URL = 'https://gachia.com';
const INDEXNOW_KEY = 'gachia2026indexnowkey';
const ENDPOINTS = ['https://api.indexnow.org/indexnow', 'https://www.bing.com/indexnow'];
const LOCALES = ['zh', 'en', 'ja'];
const GAMES = GAME_IDS;

function gitAddedFiles() {
  const output = execFileSync('git', ['-C', process.cwd(), 'status', '--porcelain=v1', '--untracked-files=all'], {
    encoding: 'utf8',
  });
  return output
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .filter((line) => line.startsWith('A ') || line.startsWith('?? '))
    .map((line) => line.slice(3).trim());
}

function toPosix(p) {
  return p.split(path.sep).join('/');
}

function routeFromAddedFile(filePath) {
  const normalized = toPosix(path.relative(process.cwd(), filePath));
  const prefix = 'apps/web/app/';
  if (!normalized.startsWith(prefix) || !normalized.endsWith('/page.tsx')) return null;

  const segments = normalized.slice(prefix.length, -'/page.tsx'.length).split('/');
  if (segments.length === 0) return null;

  if (segments[0] === '[lang]' && segments[1] === '[game]' && segments[2] === 'version') {
    return LOCALES.flatMap((lang) => GAMES.map((game) => `/${lang}/${game}/version`));
  }

  return null;
}

async function submit(urls) {
  if (urls.length === 0) {
    console.log('No new page URLs found for IndexNow.');
    return;
  }

  const urlList = [...new Set(urls)].slice(0, 10_000);
  const body = { host: 'gachia.com', key: INDEXNOW_KEY, keyLocation: `${BASE_URL}/${INDEXNOW_KEY}.txt`, urlList };
  for (const endpoint of ENDPOINTS) {
    const res = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
    console.log(`${endpoint} -> ${res.status} (${urlList.length} URLs)`);
  }

  console.log(`Submitted ${urlList.length} URLs.`);
}

const addedFiles = gitAddedFiles();
const urls = new Set();
for (const file of addedFiles) {
  const resolved = path.resolve(process.cwd(), file);
  const routeUrls = routeFromAddedFile(resolved);
  if (routeUrls) {
    for (const url of routeUrls) urls.add(url);
  }
}

await submit([...urls]);

import { NextResponse } from 'next/server';

const INDEXNOW_KEY = 'gachia2026indexnowkey';

// IndexNow API endpoint — ping search engines when content changes
export async function POST(request: Request) {
  const authToken = process.env.INDEXNOW_AUTH_TOKEN;
  if (!authToken) {
    console.error('INDEXNOW_AUTH_TOKEN is not configured');
    return NextResponse.json({ error: 'Service unavailable' }, { status: 503 });
  }

  // P1-7: Add authentication to prevent abuse
  const authHeader = request.headers.get('authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ') || authHeader.slice(7) !== authToken) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const payload: unknown = await request.json();
    const urls = isUrlPayload(payload) ? [...new Set(payload.urls)] : null;
    if (!urls) {
      return NextResponse.json({ error: 'Invalid urls array' }, { status: 400 });
    }

    if (urls.some((url) => {
      const parsedUrl = new URL(url);
      return parsedUrl.protocol !== 'https:' || parsedUrl.hostname !== 'gachia.com' || Boolean(parsedUrl.port);
    })) {
      return NextResponse.json({ error: 'Only gachia.com URLs are allowed' }, { status: 400 });
    }

    const body = {
      host: 'gachia.com',
      key: INDEXNOW_KEY,
      keyLocation: `https://gachia.com/${INDEXNOW_KEY}.txt`,
      urlList: urls,
    };

    // Ping all IndexNow-compatible search engines in parallel
    const endpoints = [
      'https://api.indexnow.org/indexnow',
      'https://www.bing.com/indexnow',
      'https://search.seznam.cz/indexnow',
      'https://yandex.com/indexnow',
    ];

    const results = await Promise.allSettled(
      endpoints.map((endpoint) =>
        fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        }).then((res) => ({ endpoint, status: res.status }))
      )
    );

    const succeeded = results.filter(
      (r) => r.status === 'fulfilled' && [200, 202, 204].includes(r.value.status)
    ).length;

    return NextResponse.json({ ok: true, notified: succeeded, total: endpoints.length });
  } catch {
    return NextResponse.json({ error: 'Invalid request' }, { status: 400 });
  }
}

function isUrlPayload(payload: unknown): payload is { urls: string[] } {
  if (!payload || typeof payload !== 'object' || !('urls' in payload)) return false;
  const urls = (payload as { urls: unknown }).urls;
  return Array.isArray(urls)
    && urls.length >= 1
    && urls.length <= 10000
    && urls.every((url) => typeof url === 'string' && url.length <= 2048 && URL.canParse(url));
}

import 'server-only';

const BASE_URL = 'https://gachia.com';

function normalizeProductionUrl(path: string): string | null {
  try {
    const url = new URL(path, BASE_URL);
    if (url.protocol !== 'https:' || url.hostname !== 'gachia.com' || url.port) return null;
    url.hash = '';
    return url.toString();
  } catch {
    return null;
  }
}

/**
 * Notify search engines about new/updated URLs via IndexNow.
 * Fire-and-forget — do not block the response.
 * CRITICAL FIX: Make this function async and add proper error handling
 */
export async function notifyIndexNow(paths: string[]): Promise<void> {
  if (!paths || paths.length === 0) {
    console.warn('notifyIndexNow called with empty paths array');
    return;
  }

  if (paths.length > 10000) {
    console.warn(`notifyIndexNow called with ${paths.length} URLs, exceeding 10000 limit`);
    return;
  }

  const urls = [...new Set(paths.map(normalizeProductionUrl).filter((url): url is string => Boolean(url)))];
  if (urls.length === 0) {
    console.warn('notifyIndexNow received no valid production URLs');
    return;
  }
  const authToken = process.env.INDEXNOW_AUTH_TOKEN;
  if (!authToken) {
    console.error('INDEXNOW_AUTH_TOKEN is not configured');
    return;
  }

  try {
    const response = await fetch(`${BASE_URL}/api/indexnow`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${authToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ urls }),
    });

    if (!response.ok) {
      console.error(`IndexNow notification failed: ${response.status}`);
    }
  } catch (error) {
    // Fire-and-forget: log error but don't throw
    console.error('IndexNow notification error:', error);
  }
}

/**
 * Notify IndexNow about a single URL (convenience function)
 */
export async function notifySingleUrl(path: string): Promise<void> {
  return notifyIndexNow([path]);
}

/**
 * Notify IndexNow about character page updates
 */
export async function notifyCharacterUpdate(gameId: string, characterId: string): Promise<void> {
  const paths = ['zh', 'en', 'ja'].map((lang) => `/${lang}/${gameId}/characters/${characterId}`);
  await notifyIndexNow(paths);
}

/**
 * Notify IndexNow about game page updates
 */
export async function notifyGameUpdate(gameId: string): Promise<void> {
  const paths = ['zh', 'en', 'ja'].map((lang) => `/${lang}/${gameId}/characters`);
  await notifyIndexNow(paths);
}
